import{promises as fs}from'node:fs';for(const p of['scripts/build.mjs','assets/atlas.css'])await fs.access(p).catch(()=>{throw new Error(`Eksik: ${p}. Repo kökünde çalıştır.`)});const append=async(f,p,m)=>{let s=await fs.readFile(f,'utf8');if(!s.includes(m)){s+='\n'+await fs.readFile(p,'utf8');await fs.writeFile(f,s)}};await append('scripts/build.mjs','v23-build-patch.txt','V23 Policy Atlas Article Audio Reader');await append('assets/atlas.css','v23-css-patch.txt','V23 Article Audio Reader');await fs.copyFile('article-reader.js','assets/article-reader.js');console.log('V23 kuruldu: cihaz tabanlı sesli makale okuyucu eklendi.');
